schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "faion://ai-llm-workload-architecture/output.schema.json",
  "title": "AI LLM workload architecture spec",
  "type": "object",
  "required": [
    "feature_name", "eval_set", "scoring", "baseline_run", "metrics",
    "regression_gate", "production_model_id", "budgets",
    "untrusted_input_channels", "degradation", "evidence"
  ],
  "additionalProperties": false,
  "definitions": {
    "pinned_model_id": {
      "type": "string",
      "minLength": 3,
      "pattern": "(\\d{4}-\\d{2}-\\d{2}|\\d{8}|@\\d+|:\\d+|-v\\d+(\\.\\d+)*$)",
      "not": {"pattern": "(?i)(^|[-:@/_])latest$"},
      "description": "dated (YYYYMMDD / YYYY-MM-DD) or explicitly versioned (@N, :N, -vN); never an alias"
    },
    "sha256": {"type": "string", "pattern": "^sha256:[0-9a-f]{64}$"},
    "case_ids": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 1}}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "feature_name": {"type": "string", "minLength": 3},
    "owner": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "eval_set": {
      "type": "object",
      "required": ["path", "ref", "case_count", "contamination_check_passed"],
      "additionalProperties": false,
      "properties": {
        "path": {"type": "string", "minLength": 3, "not": {"pattern": "\\.ipynb$"}},
        "ref": {"type": "string", "pattern": "^([0-9a-f]{7,40}|sha256:[0-9a-f]{64})$", "description": "git ref or content hash - the eval_set_ref input"},
        "case_count": {"type": "integer", "minimum": 1},
        "contamination_check_passed": {"type": "boolean", "const": true},
        "contamination_check_job": {"type": "string"}
      }
    },
    "scoring": {
      "type": "object",
      "required": ["kind"],
      "additionalProperties": false,
      "properties": {
        "kind": {"type": "string", "enum": ["exact-match", "regex", "json-schema", "unit-assertion", "llm-judge"]},
        "judge": {
          "type": "object",
          "required": ["model_id", "temperature", "prompt_hash", "noise_floor"],
          "additionalProperties": false,
          "properties": {
            "model_id": {"$ref": "#/definitions/pinned_model_id"},
            "temperature": {"type": "number", "const": 0},
            "prompt_hash": {"$ref": "#/definitions/sha256"},
            "noise_floor": {"type": "number", "minimum": 0, "description": "max score delta between two runs at the same commit"}
          }
        }
      },
      "if": {"properties": {"kind": {"const": "llm-judge"}}},
      "then": {"required": ["judge"]}
    },
    "baseline_run": {
      "type": "object",
      "required": ["url", "commit"],
      "additionalProperties": false,
      "properties": {
        "url": {"type": "string", "format": "uri"},
        "commit": {"type": "string", "pattern": "^[0-9a-f]{7,40}$"},
        "run_at": {"type": "string", "format": "date"}
      }
    },
    "metrics": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["name", "baseline", "tolerance", "threshold", "direction"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 2},
          "baseline": {"type": "number"},
          "tolerance": {"type": "number", "description": "signed allowance from baseline; negative for higher-is-better metrics"},
          "threshold": {"type": "number", "description": "baseline plus tolerance"},
          "direction": {"type": "string", "enum": ["higher-is-better", "lower-is-better"]}
        }
      }
    },
    "regression_gate": {
      "type": "object",
      "required": ["ci_job", "blocks_merge", "watched_paths", "prompts_in_version_control"],
      "additionalProperties": false,
      "properties": {
        "ci_job": {"type": "string", "minLength": 2},
        "blocks_merge": {"type": "boolean", "const": true},
        "watched_paths": {"type": "array", "minItems": 2, "items": {"type": "string", "minLength": 2}, "description": "prompts, model config, retrieval config, tool schemas"},
        "prompts_in_version_control": {"type": "boolean", "const": true},
        "prompt_hash_logged_at_startup": {"type": "boolean"}
      }
    },
    "production_model_id": {"$ref": "#/definitions/pinned_model_id"},
    "budgets": {
      "type": "object",
      "required": ["p95_latency_ms", "per_request", "measured_in_eval_run"],
      "additionalProperties": false,
      "properties": {
        "p95_latency_ms": {"type": "integer", "minimum": 1},
        "per_request": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "tokens": {"type": "integer", "minimum": 1},
            "cost_usd": {"type": "number", "exclusiveMinimum": 0}
          },
          "anyOf": [{"required": ["tokens"]}, {"required": ["cost_usd"]}]
        },
        "measured_in_eval_run": {"type": "boolean", "const": true}
      }
    },
    "untrusted_input_channels": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["channel", "kind", "injection_case_ids"],
        "additionalProperties": false,
        "properties": {
          "channel": {"type": "string", "minLength": 2},
          "kind": {"type": "string", "enum": ["retrieval-source", "tool-output", "user-turn"]},
          "injection_case_ids": {"$ref": "#/definitions/case_ids"}
        }
      }
    },
    "degradation": {
      "type": "object",
      "required": ["retry", "fallback", "user_message"],
      "additionalProperties": false,
      "properties": {
        "retry": {
          "type": "object",
          "required": ["max_attempts", "backoff", "base_delay_ms"],
          "additionalProperties": false,
          "properties": {
            "max_attempts": {"type": "integer", "minimum": 0, "maximum": 10},
            "backoff": {"type": "string", "enum": ["exponential-with-jitter", "exponential", "fixed"]},
            "base_delay_ms": {"type": "integer", "minimum": 1},
            "triggers": {"type": "array", "items": {"type": "string", "enum": ["timeout", "429", "5xx"]}}
          }
        },
        "fallback": {
          "type": "object",
          "required": ["kind", "eval_case_ids"],
          "additionalProperties": false,
          "properties": {
            "kind": {"type": "string", "enum": ["secondary-pinned-model", "cached-answer", "explicit-refusal"]},
            "model_id": {"$ref": "#/definitions/pinned_model_id"},
            "eval_case_ids": {"$ref": "#/definitions/case_ids"}
          },
          "if": {"properties": {"kind": {"const": "secondary-pinned-model"}}},
          "then": {"required": ["model_id"]}
        },
        "user_message": {"type": "string", "minLength": 10}
      }
    },
    "evidence": {"type": "array", "minItems": 1, "items": {"type": "string", "format": "uri"}}
  }
}

output-contract.example:
{
  "feature_name": "support-ticket summariser",
  "owner": "swe:alice",
  "eval_set": {
    "path": "evals/summariser/cases.jsonl",
    "ref": "a1b2c3d4e5f",
    "case_count": 142,
    "contamination_check_passed": true,
    "contamination_check_job": "ci/eval-contamination-grep"
  },
  "scoring": {
    "kind": "llm-judge",
    "judge": {
      "model_id": "claude-sonnet-4-5-20250929",
      "temperature": 0,
      "prompt_hash": "sha256:fc97a67bbfa1c1d346e731e6ef96eab3c1df8690b53a58d814792cf5bffe218c",
      "noise_floor": 0.01
    }
  },
  "baseline_run": {
    "url": "https://ci.example.com/evals/summariser/run/4410",
    "commit": "7c9e2f1a3b",
    "run_at": "2026-03-04"
  },
  "metrics": [
    {"name": "answer_accuracy", "baseline": 0.89, "tolerance": -0.02, "threshold": 0.87, "direction": "higher-is-better"},
    {"name": "hallucination_rate", "baseline": 0.03, "tolerance": 0.01, "threshold": 0.04, "direction": "lower-is-better"},
    {"name": "injection_resistance", "baseline": 1.0, "tolerance": 0.0, "threshold": 1.0, "direction": "higher-is-better"}
  ],
  "regression_gate": {
    "ci_job": "eval-summariser",
    "blocks_merge": true,
    "watched_paths": ["prompts/summariser/", "config/models.yaml", "config/retrieval.yaml", "tools/schemas/"],
    "prompts_in_version_control": true,
    "prompt_hash_logged_at_startup": true
  },
  "production_model_id": "claude-sonnet-4-5-20250929",
  "budgets": {
    "p95_latency_ms": 2500,
    "per_request": {"tokens": 6000, "cost_usd": 0.02},
    "measured_in_eval_run": true
  },
  "untrusted_input_channels": [
    {"channel": "ticket body (retrieval)", "kind": "retrieval-source", "injection_case_ids": ["inj-ticket-001", "inj-ticket-002"]},
    {"channel": "kb-search tool output", "kind": "tool-output", "injection_case_ids": ["inj-kb-001"]},
    {"channel": "agent user turn", "kind": "user-turn", "injection_case_ids": ["inj-user-001"]}
  ],
  "degradation": {
    "retry": {"max_attempts": 3, "backoff": "exponential-with-jitter", "base_delay_ms": 500, "triggers": ["timeout", "429", "5xx"]},
    "fallback": {"kind": "secondary-pinned-model", "model_id": "claude-haiku-4-5-20251001", "eval_case_ids": ["deg-429-001", "deg-timeout-001"]},
    "user_message": "Summary temporarily unavailable; showing the ticket as filed."
  },
  "evidence": [
    "https://ci.example.com/evals/summariser/run/4410",
    "https://ci.example.com/evals/summariser/run/4411",
    "https://github.com/acme/support/pull/2210"
  ]
}

{
  "feature_name": "support-ticket summariser",
  "owner": "swe:alice",
  "eval_set": {
    "path": "notebooks/eval-playground.ipynb",
    "ref": "a1b2c3d4e5f",
    "case_count": 40,
    "contamination_check_passed": true
  },
  "scoring": {
    "kind": "llm-judge",
    "judge": {
      "model_id": "claude-latest",
      "temperature": 0.7,
      "prompt_hash": "sha256:fc97a67bbfa1c1d346e731e6ef96eab3c1df8690b53a58d814792cf5bffe218c",
      "noise_floor": 0.06
    }
  },
  "baseline_run": {
    "url": "https://ci.example.com/evals/summariser/run/4410",
    "commit": "7c9e2f1a3b"
  },
  "metrics": [
    {"name": "answer_accuracy", "baseline": 0.89, "tolerance": -0.02, "threshold": 0.87, "direction": "higher-is-better"}
  ],
  "regression_gate": {
    "ci_job": "eval-summariser",
    "blocks_merge": false,
    "watched_paths": ["prompts/summariser/"],
    "prompts_in_version_control": true
  },
  "production_model_id": "gpt-4o-latest",
  "budgets": {
    "p95_latency_ms": 2500,
    "per_request": {"tokens": 6000},
    "measured_in_eval_run": false
  },
  "untrusted_input_channels": [
    {"channel": "ticket body (retrieval)", "kind": "retrieval-source", "injection_case_ids": []}
  ],
  "degradation": {
    "retry": {"max_attempts": 100, "backoff": "fixed", "base_delay_ms": 100},
    "fallback": {"kind": "explicit-refusal", "eval_case_ids": []},
    "user_message": "Error"
  },
  "evidence": [
    "https://ci.example.com/evals/summariser/run/4410"
  ]
}
